import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem123 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["PEegqDESPIk3onguTRg8","Ddpai N1 Dual Câmera Veicular 1296p+1080p Uber Nightvis App","Câmera veicular DDPAI N1 Dual — 1296p frontal e 1080p traseiros anunciados","https://www.mercadolivre.com.br/up/MLBU1756154230?pdp_filters=item_id%3AMLB5010641270"],["pEszDEGUnKoIpY9xhIdV","Perfume Masculino Premium Midnight Blue 100ml Original Árabe","Perfume masculino Midnight Blue — 100 mL anunciados","https://www.mercadolivre.com.br/up/MLBU3780254973?pdp_filters=item_id%3AMLB4470176627"],["pGWith3ABAHWNTRZG3fM","PENTA MAGNÉSIO - Bisglicinato + Dimalato + Citrato + Taurato + Óxido de Magnésio - A Combinação Perfeita de 5 Magnésios com Máxima Pureza e Biodisponibilidade - 60 Cápsulas","Penta Magnésio Essencial Labs — 60 cápsulas anunciadas","https://www.mercadolivre.com.br/p/MLB61669343?pdp_filters=item_id%3AMLB4291609113"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
